import sys
import pandas as pd
from openpyxl import load_workbook

path = sys.argv[1]

try:
    wbv = load_workbook(path, data_only=True, read_only=True)
except Exception as e:
    wbv = None
    print("openpyxl cached read failed:", e)

sheets = pd.read_excel(path, sheet_name=None, header=None)
for name, df in sheets.items():
    print(f"=== Sheet: {name} ({df.shape[0]}r x {df.shape[1]}c) ===")
    for i in range(df.shape[0]):
        vals = []
        for v in df.iloc[i].tolist():
            if pd.isna(v):
                vals.append("<NA>")
            else:
                vals.append(repr(v))
        print(f"r{i}: " + " | ".join(vals))
    if wbv is not None and name in wbv.sheetnames:
        print("-- cached values (formulas resolved) --")
        for ri, row in enumerate(wbv[name].iter_rows(values_only=True)):
            print(f"r{ri}: " + " | ".join("<NA>" if v is None else repr(v) for v in row))

